:root {
  color-scheme: dark;
  --ink: #070a11;
  --gold: #f0b35a;
  --teal: #7fe4d4;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: #e8e2d4;
  font-family: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
  outline: none;
}

#boot {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: radial-gradient(circle at 50% 45%, #131a26 0%, #070a11 68%);
  z-index: 10;
  transition: opacity 700ms ease, visibility 700ms;
}

#boot.hidden { opacity: 0; visibility: hidden; }

.boot-mark {
  font-size: 54px;
  color: var(--gold);
  animation: breathe 2.4s ease-in-out infinite;
  text-shadow: 0 0 32px rgba(240, 179, 90, 0.45);
}

.boot-label {
  font-size: 11px;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: #8f9aab;
}

@keyframes breathe {
  0%, 100% { opacity: 0.45; transform: scale(0.94) rotate(0deg); }
  50% { opacity: 1; transform: scale(1.04) rotate(45deg); }
}

@media (max-width: 600px) {
  .boot-mark { font-size: 42px; }
  .boot-label { font-size: 9px; }
}

// Input: keyboard, mouse, and multi-touch (virtual stick + action buttons).
export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.queue = new Map();
    this.mouse = { x: 0, y: 0, down: false, right: false, inside: false };
    this.touchMode = false;
    this.stick = { id: null, active: false, ox: 0, oy: 0, x: 0, y: 0, dx: 0, dy: 0 };
    this.buttons = [];
    this.held = new Set();
    this.pointers = new Map();
    this.anyGesture = false;
    this.onGesture = null;

    this._bindKeyboard();
    this._bindPointer();
    this.resize(window.innerWidth, window.innerHeight);
  }

  resize(w, h) {
    this.w = w;
    this.h = h;
    this.compact = Math.min(w, h) < 620;
    const m = this.compact ? 22 : 34;
    const s = this.compact ? 0.9 : 1;
    // Right-hand action cluster, kept inside phone safe areas.
    this.buttons = [
      { id: 'attack', label: 'STRIKE', glyph: '⚔', x: w - m - 56 * s, y: h - m - 58 * s, r: 46 * s, primary: true },
      { id: 'pull', label: 'TETHER', glyph: '✦', x: w - m - 156 * s, y: h - m - 40 * s, r: 34 * s },
      { id: 'dash', label: 'DASH', glyph: '»', x: w - m - 52 * s, y: h - m - 166 * s, r: 32 * s },
    ];
    this.pauseBtn = { x: w - m - 12, y: m + 12, r: 20 };
    this.stick.base = { x: m + 66 * s, y: h - m - 74 * s, r: 58 * s };
    if (this.stick.active) {
      this.stick.ox = this.stick.base.x;
      this.stick.oy = this.stick.base.y;
    }
  }

  _emit(action) {
    this.queue.set(action, (this.queue.get(action) || 0) + 1);
    this.anyGesture = true;
    this.onGesture?.();
  }

  take(action) {
    const n = this.queue.get(action) || 0;
    if (n > 0) {
      this.queue.delete(action);
      return true;
    }
    return false;
  }

  clear() {
    this.queue.clear();
  }

  _bindKeyboard() {
    const blocked = new Set([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright', 'shift', 'tab']);
    window.addEventListener('keydown', (e) => {
      const k = e.key.toLowerCase();
      if (blocked.has(k)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(k);
      if (k === ' ' || k === 'shift') this._emit('dash');
      else if (k === 'j' || k === 'f') this._emit('attack');
      else if (k === 'e' || k === 'q') this._emit('pull');
      else if (k === 'escape' || k === 'p') this._emit('pause');
      else if (k === 'enter' || k === 'r') this._emit('confirm');
      this.anyGesture = true;
      this.onGesture?.();
    }, { passive: false });
    window.addEventListener('keyup', (e) => this.keys.delete(e.key.toLowerCase()));
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.mouse.down = false;
      this.mouse.right = false;
      this.held.clear();
    });
  }

  _bindPointer() {
    const c = this.canvas;
    const setMouse = (e) => {
      const r = c.getBoundingClientRect();
      this.mouse.x = e.clientX - r.left;
      this.mouse.y = e.clientY - r.top;
      this.mouse.inside = true;
    };

    c.addEventListener('contextmenu', (e) => e.preventDefault());

    c.addEventListener('pointerdown', (e) => {
      const r = c.getBoundingClientRect();
      const x = e.clientX - r.left;
      const y = e.clientY - r.top;
      this.pointers.set(e.pointerId, { x, y, type: e.pointerType });
      this.anyGesture = true;
      this.onGesture?.();

      if (e.pointerType === 'mouse') {
        setMouse(e);
        if (e.button === 0) {
          this.mouse.down = true;
          this._emit('attack');
        } else if (e.button === 2) {
          this.mouse.right = true;
          this._emit('pull');
        }
        return;
      }

      this.touchMode = true;
      e.preventDefault();

      // Pause button.
      if (Math.hypot(x - this.pauseBtn.x, y - this.pauseBtn.y) < this.pauseBtn.r * 1.8) {
        this._emit('pause');
        return;
      }

      // Action buttons.
      for (const b of this.buttons) {
        if (Math.hypot(x - b.x, y - b.y) < b.r * 1.32) {
          this.held.add(b.id);
          this._emit(b.id);
          return;
        }
      }

      // Virtual stick anywhere on the left portion of the screen.
      if (x < this.w * 0.55 && !this.stick.active) {
        this.stick.id = e.pointerId;
        this.stick.active = true;
        this.stick.ox = x;
        this.stick.oy = y;
        this.stick.x = x;
        this.stick.y = y;
        this.stick.dx = 0;
        this.stick.dy = 0;
      }
    }, { passive: false });

    c.addEventListener('pointermove', (e) => {
      const r = c.getBoundingClientRect();
      const x = e.clientX - r.left;
      const y = e.clientY - r.top;
      if (e.pointerType === 'mouse') {
        setMouse(e);
        return;
      }
      if (this.pointers.has(e.pointerId)) {
        this.pointers.set(e.pointerId, { x, y, type: e.pointerType });
      }
      if (this.stick.active && this.stick.id === e.pointerId) {
        this.stick.x = x;
        this.stick.y = y;
        const dx = x - this.stick.ox;
        const dy = y - this.stick.oy;
        const len = Math.hypot(dx, dy);
        const max = this.stick.base.r;
        if (len > max) {
          this.stick.ox += dx * (1 - max / len);
          this.stick.oy += dy * (1 - max / len);
        }
        const nx = (x - this.stick.ox) / max;
        const ny = (y - this.stick.oy) / max;
        const nl = Math.hypot(nx, ny);
        this.stick.dx = nl > 1 ? nx / nl : nx;
        this.stick.dy = nl > 1 ? ny / nl : ny;
      }
    }, { passive: false });

    const end = (e) => {
      if (e.pointerType === 'mouse') {
        if (e.button === 0) this.mouse.down = false;
        if (e.button === 2) this.mouse.right = false;
      }
      this.pointers.delete(e.pointerId);
      if (this.stick.active && this.stick.id === e.pointerId) {
        this.stick.active = false;
        this.stick.id = null;
        this.stick.dx = 0;
        this.stick.dy = 0;
      }
      // Release held buttons belonging to this pointer.
      if (e.pointerType !== 'mouse') {
        for (const b of this.buttons) {
          const p = { x: e.clientX, y: e.clientY };
          if (this.held.has(b.id) && Math.hypot(p.x - b.x, p.y - b.y) < b.r * 1.5) this.held.delete(b.id);
        }
        if (this.held.size === 0) this.held.clear();
      }
    };
    c.addEventListener('pointerup', end);
    c.addEventListener('pointercancel', end);
    c.addEventListener('pointerleave', (e) => {
      if (e.pointerType === 'mouse') this.mouse.inside = false;
    });

    // Fallback for browsers that fire touch events but no pointer events.
    c.addEventListener('touchstart', (e) => e.preventDefault(), { passive: false });
  }

  get move() {
    let x = 0;
    let y = 0;
    if (this.keys.has('a') || this.keys.has('arrowleft')) x -= 1;
    if (this.keys.has('d') || this.keys.has('arrowright')) x += 1;
    if (this.keys.has('w') || this.keys.has('arrowup')) y -= 1;
    if (this.keys.has('s') || this.keys.has('arrowdown')) y += 1;
    if (this.stick.active) {
      x += this.stick.dx;
      y += this.stick.dy;
    }
    const len = Math.hypot(x, y);
    if (len > 1) {
      x /= len;
      y /= len;
    }
    return { x, y, len: Math.min(1, len) };
  }

  get attackHeld() {
    return this.mouse.down || this.held.has('attack');
  }
}

